import{predictRow,encodeFields}from'./engine.mjs';
const $=id=>document.getElementById(id),form=$('car-form'),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);let model,last='';
for(const b of document.querySelectorAll('[data-page]'))b.addEventListener('click',()=>{for(const p of document.querySelectorAll('.page'))p.hidden=p.id!=='page-'+b.dataset.page;for(const n of document.querySelectorAll('nav button'))n.classList.toggle('active',n===b);window.scrollTo({top:0,behavior:'smooth'});});
const current=()=>Object.fromEntries(new FormData(form));
function fillModels(){const values=model.catalog[$('manufacturer').value.toLowerCase().trim()]||[];$('models').replaceChildren(...values.map(v=>{const o=document.createElement('option');o.value=v;return o;}));}
$('manufacturer').addEventListener('input',()=>{if(model)fillModels();});
form.addEventListener('input',()=>{if(last&&JSON.stringify(current())!==last)$('status').textContent='Details changed. Estimate again to update the price.';});
form.addEventListener('submit',event=>{event.preventDefault();if(!model||!form.reportValidity())return;const fields=current(),price=predictRow(encodeFields(fields,model),model),log=Math.log1p(price),band=[Math.expm1(Math.max(0,log-model.band)),Math.expm1(Math.min(Math.log1p(1e7),log+model.band))];last=JSON.stringify(fields);$('empty').hidden=true;$('estimate-result').hidden=false;$('result-car').textContent=`${fields.year} ${fields.manufacturer} ${fields.model}`;$('price').textContent=money(Math.round(price/50)*50);$('range').textContent=band.map(n=>money(Math.round(n/50)*50)).join(' – ');const unknown=['manufacturer','model'].filter(k=>model.schema[k].indexOf(fields[k].toLowerCase().trim())<0);$('status').textContent=+fields.year>2021?'Estimate ready. This year is newer than the 2021 training snapshot.':unknown.length?'Estimate ready. An entered make/model was unseen in training and treated as missing.':'Estimate ready · trained tabular baseline · 2021 asking-price data.';if(innerWidth<741)$('estimate-result').scrollIntoView({behavior:'smooth',block:'center'});});
const presets={commuter:{manufacturer:'toyota',model:'corolla',year:2015,odometer:95000,type:'sedan',condition:'good',fuel:'gas',transmission:'automatic',state:'ca'},truck:{manufacturer:'ford',model:'f-150',year:2017,odometer:80000,type:'pickup',condition:'good',fuel:'gas',transmission:'automatic',state:'tx'},suv:{manufacturer:'honda',model:'cr-v',year:2018,odometer:62000,type:'SUV',condition:'excellent',fuel:'gas',transmission:'automatic',state:'ca'}};
for(const b of document.querySelectorAll('[data-example]'))b.addEventListener('click',()=>{if(!model)return;for(const[k,v]of Object.entries(presets[b.dataset.example])){const el=$(k);el.value=String(v).toLowerCase();}fillModels();$('status').textContent='Example loaded. Select Estimate asking price to calculate.';});
try{const r=await fetch('./baseline-model.json');if(!r.ok)throw Error('Model unavailable');model=await r.json();for(const[k,values]of Object.entries(model.schema)){const el=$(k);if(k==='manufacturer'){$('makes').replaceChildren(...values.map(v=>{const o=document.createElement('option');o.value=v;return o;}));continue;}if(k==='model')continue;el.replaceChildren(new Option('Unknown',''),...values.map(v=>new Option(v,v)));}for(const[k,v]of Object.entries(presets.commuter))$(k).value=String(v).toLowerCase();fillModels();$('estimate').disabled=false;$('estimate').innerHTML='Estimate asking price <span>↗</span>';$('status').textContent='Ready. Edit the details or use an example.';const m=model.meta;for(const[value,label]of[[money(m.test.mae_usd),'Mean absolute test error'],[money(m.test.rmse_usd),'Test RMSE'],[m.test.median_ape_pct.toFixed(1)+'%','Median absolute percentage error'],[m.test.r2.toFixed(3),'Test R²']]){const div=document.createElement('div');div.className='metric';const n=document.createElement('strong'),t=document.createElement('span');n.textContent=value;t.textContent=label;div.append(n,t);$('metrics').append(div);}$('cohort').textContent=`${m.raw_sample_rows.toLocaleString('en-US')} raw listings scanned; ${m.eligible_rows.toLocaleString('en-US')} eligible/deduplicated. Assessment training: ${m.train_rows.toLocaleString('en-US')}; validation: ${m.validation_rows.toLocaleString('en-US')}; held-out test: ${m.test_rows.toLocaleString('en-US')}.`;$('refit-scope').textContent=`Deployment refit: ${(m.deployment_refit_rows||m.train_rows).toLocaleString('en-US')} eligible rows. The deployment model has no independent holdout; the error band reuses assessment residuals.`;$('coverage').textContent=`The validation-calibrated 80% band covered ${(m.band80_test_coverage*100).toFixed(1)}% of test listing prices. The selected baseline uses ${m.selected.target} targets and Huber threshold ${m.selected.alpha}.`;}catch(e){$('estimate').textContent='Model unavailable';$('status').classList.add('error');$('status').textContent='The trained baseline could not be loaded. Refresh to retry. No estimate has been generated.';}
